const raw = $json.message.content;

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error("Ollama returned invalid JSON: " + raw);
}

const medications = (parsed.medications || []).map(med => ({
  medication_name: med.medication_name || "Not specified",
  dosage: med.dosage || "Not specified",
  frequency: med.frequency || "Not specified",
  timing: med.timing || "Not specified",
  before_or_after_food: med.before_or_after_food || "Not specified",
  duration: med.duration || "Not specified"
}));

// Generate a reminder preview for each medication
const reminderPreview = medications.map(med => ({
  medication: med.medication_name,
  dosage: med.dosage,
  frequency: med.frequency,
  reminder_time: med.timing,
  food_instruction: med.before_or_after_food,
  duration: med.duration,
  message: `Reminder: It is time for your ${medicationName(med)}.`
}));

function medicationName(med) {
  return `${med.medication_name} (${med.dosage})`;
}

return [{
  json: {
    medications,
    reminder_preview: reminderPreview,
    verified: false,
    requires_confirmation: true
  }
}];

